        <Self as semio_framework_value::FromValue>::from_value(semio_framework_pack_json::to_dsl_value(&parsed)).map_err(|error| protocol::ProtocolError::Malformed { what: "Ifc2x3SavEditCommand", offset: 0, detail: error.to_string() })
    }
}
